from pathlib import Path
R=Path('/mnt/data/gramos_v41_work/tests')
def patch(name,old,new):
 p=R/name;s=p.read_text();n=s.count(old)
 if n!=1:raise Exception(f'{name}: expected 1 got {n}, old {old[:50]}')
 p.write_text(s.replace(old,new))
patch('home-data.mjs',"assert(page.includes('चाचणी कॉपीराइट'),'Editable copyright must display from village settings');", "assert(page.includes('Copyright © 2026')&&page.includes('Swaraj Gram Soft and Software Private Limited'),'Fixed company legal line must be visible');\nassert(!page.includes('चाचणी कॉपीराइट'),'Old village copyright must not override fixed company text');")
