s=s.replace("for(const key of ['copyright_mr','copyright_en','credit_mr','credit_en','footer_social_heading_mr']){\n assert(admin.includes(key)||admin.includes(`'${key.split('_')[0]}'`),`${key} missing from admin`);\n}","assert(admin.includes('platformLegalNotice()'));\nassert(!admin.includes(\"['footer_social_heading_mr'\"));")
